const webhookData = $('互動事件 Webhook').first().json;
const body = webhookData.body || webhookData || {};
const ALLOWED_CHANNELS = new Set(['threads', 'ig', 'line', '']);

function cleanCell(val, maxLen) {
  if (val === undefined || val === null) return '';
  let s = String(val).trim().slice(0, maxLen);
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
  return s;
}

function isSafeHttpsUrl(rawUrl) {
  try {
    const u = new URL(String(rawUrl || '').trim());
    return u.protocol === 'https:';
  } catch (_) {
    return false;
  }
}

const action = String(body.action || '').trim();
const userId = cleanCell(body.userId, 64);
const displayName = cleanCell(body.displayName, 60);
const storeId = cleanCell(body.storeId, 40);
const rawChannel = String(body.channel || '').trim();
const channel = ALLOWED_CHANNELS.has(rawChannel) ? rawChannel : '';
const rawPostUrl = String(body.postUrl || '').trim().slice(0, 300);

if (!userId) {
  return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, message: '缺少 userId' }) } }];
}

const now = new Date();
const twNow = new Date(now.getTime() + 8 * 3600 * 1000);
const today = twNow.toISOString().slice(0, 10);
const twIso = twNow.toISOString().replace('Z', '+08:00');

const rows = $input.all().map((i) => i.json).filter((r) => r['玩家LINE'] || r.userId);
const userTodayEvents = rows.filter((r) => String(r['玩家LINE'] || '') === userId && String(r['日期'] || '') === today);

function calcPoints(uid) {
  return rows
    .filter((r) => String(r['玩家LINE'] || '') === uid)
    .reduce((sum, r) => sum + (parseInt(r['點數'] || '0', 10) || 0), 0);
}

function levelByPoints(pts) {
  if (pts >= 100) return '🏆 互推達人';
  if (pts >= 20) return '🔥 熱心店家';
  return '🌱 新芽';
}

if (action === 'get_profile') {
  const pts = calcPoints(userId);
  return [{
    json: {
      writeEvent: false,
      notifyAdmin: false,
      res: JSON.stringify({ ok: true, points: pts, level: levelByPoints(pts), role: '玩家' })
    }
  }];
}

if (action === 'visit') {
  if (!storeId) {
    return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, message: '缺少 storeId' }) } }];
  }
  const visitsToday = userTodayEvents.filter((r) => r['動作'] === 'visit');
  if (visitsToday.some((r) => String(r['店家編號'] || '') === storeId)) {
    return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, reason: 'already_visited_today' }) } }];
  }
  if (visitsToday.length >= 20) {
    return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, reason: 'daily_limit_reached' }) } }];
  }
  return [{
    json: {
      writeEvent: true,
      notifyAdmin: false,
      eventRow: {
        '時間': twIso,
        '日期': today,
        '玩家LINE': userId,
        '暱稱': displayName,
        '動作': 'visit',
        '店家編號': storeId,
        '管道': channel,
        '點數': 1,
        '備註': '去逛一次'
      },
      res: JSON.stringify({ ok: true, delta: 1 })
    }
  }];
}

if (action === 'share') {
  const sharesToday = userTodayEvents.filter((r) => r['動作'] === 'share');
  if (sharesToday.length >= 5) {
    return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, reason: 'share_limit_reached' }) } }];
  }
  return [{
    json: {
      writeEvent: true,
      notifyAdmin: false,
      eventRow: {
        '時間': twIso,
        '日期': today,
        '玩家LINE': userId,
        '暱稱': displayName,
        '動作': 'share',
        '店家編號': storeId,
        '管道': 'line',
        '點數': 3,
        '備註': 'LINE 分享'
      },
      res: JSON.stringify({ ok: true, delta: 3 })
    }
  }];
}

if (action === 'submit_collab') {
  if (!isSafeHttpsUrl(rawPostUrl)) {
    return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, message: '貼文連結必須為有效的 https:// 網址' }) } }];
  }
  const safePostUrl = cleanCell(rawPostUrl, 300);
  return [{
    json: {
      writeEvent: true,
      notifyAdmin: true,
      notifyText: `🤝 互推貼文回報\n玩家：${displayName || userId}\n連結：${rawPostUrl}`,
      eventRow: {
        '時間': twIso,
        '日期': today,
        '玩家LINE': userId,
        '暱稱': displayName,
        '動作': 'collab_post',
        '店家編號': storeId,
        '管道': 'threads',
        '點數': 0,
        '備註': safePostUrl
      },
      res: JSON.stringify({ ok: true, message: '已送出，等待管理員確認加分' })
    }
  }];
}

return [{ json: { writeEvent: false, notifyAdmin: false, res: JSON.stringify({ ok: false, message: '未知 action' }) } }];
